import fs from 'node:fs/promises';import path from 'node:path';
const root=path.resolve('EVA_PRINT_WEBSITE_BRIEF_2026-10-02');const records=JSON.parse(await fs.readFile(path.join(root,'02_MATERIALS/materials.en.json')));const man=JSON.parse(await fs.readFile(path.join(root,'09_SOURCES/download-manifest.json')));
const poly=JSON.parse(await fs.readFile(path.join(root,'09_SOURCES/polymaker-shop-products.json'))).products;const fill=JSON.parse(await fs.readFile(path.join(root,'09_SOURCES/fillamentum-shop-products.json'))).products;
async function get(u,rel,kind,source){try{const r=await fetch(u,{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('HTTP '+r.status);const b=Buffer.from(await r.arrayBuffer());if(kind==='pdf'&&b.subarray(0,5).toString()!=='%PDF-')throw Error('Not PDF');await fs.mkdir(path.dirname(path.join(root,rel)),{recursive:true});await fs.writeFile(path.join(root,rel),b);const v={url:u,final_url:r.url,path:rel,kind,status:'downloaded',bytes:b.length,source_page:source,publication_rights:kind==='image'?'reference_only_permission_required':'manufacturer_reference',checked_at:'2026-10-02'};man.push(v);return v;}catch(e){return null;}}
async function pool(a,fn,n=6){let i=0;await Promise.all(Array.from({length:n},async()=>{while(i<a.length)await fn(a[i++]);}));}
const handles={
 'PLA High Temperature':'polymaker-ht-pla','PLA High Temperature Glass Fiber':'polymaker-ht-pla-gf','PLA Lightweight':'polylite-lw-pla','PLA Tough':'polymax-pla','PLA Carbon Fiber':'polylite-pla-cf','PA6 Carbon Fiber':'fiberon-pa6-cf20','PA6 Glass Fiber':'fiberon-pa6-gf25','PA612 Carbon Fiber':'fiberon-pa612-cf','PA612 ESD':'fiberon-pa612-esd','PA12 Carbon Fiber':'fiberon-pa12-cf10','PA6 PA66 Copolymer':'polymide-copa','PET Carbon Fiber':'fiberon-pet-cf17','PETG Recycled Carbon Fiber':'fiberon-petg-rcf08','PC Flame Retardant':'polymax-pc-fr','TPU 90A':'polyflex-tpu90','TPU 95A High Flow':'polyflex-tpu95-hf','Water Soluble Support S1':'polydissolve-s1','Breakaway Support for PLA':'polysupport-for-pla','Breakaway Support for PA12':'polysupport'
};
await pool(records,async m=>{if(m.brand==='Polymaker'||m.brand==='Fillamentum'){let products=m.brand==='Polymaker'?poly:fill;let prod=m.brand==='Polymaker'?products.find(x=>x.handle===handles[m.material_name]):products.find(x=>!/^\d+\s*m\s*Sample/.test(x.title)&&x.title.toLowerCase().includes(m.material_name.replace(/^PA Nylon /,'Nylon ').replace(/^Wood Composite /,'').replace(/^Biopolymer /,'').toLowerCase()));
 if(!prod&&m.brand==='Fillamentum'){let key=m.material_name.match(/PEBA|TPE \d+A|TPU \d+A|AF80|CF15|FX256|NonOilen|Timberfill|HG100|CF112|2320|Crystal Clear/)?.[0];if(key)prod=products.find(x=>!x.title.includes('Sample')&&x.title.includes(key.replace('TPU ','')));}
 if(prod){const source='https://shop.'+m.brand.toLowerCase()+'.com/products/'+prod.handle;m.product_source_url=source;if(!m.source_url||m.source_url.endsWith('.pdf'))m.source_url=source;
 m.manufacturer_product_title=prod.title;m.supplier_variants=(prod.variants||[]).map(v=>({supplier_sku:v.sku||null,title:v.title,available_at_supplier:v.available,diameter_note:'Verify 1.75 mm variant before ordering; variant titles can include multiple diameters.',source_url:source}));
 for(const [i,img] of (prod.images||[]).slice(0,3).entries()){let ext=new URL(img.src).pathname.match(/\.(png|jpg|jpeg|webp)$/i)?.[1]||'jpg';let d=await get(img.src,'04_REFERENCE_PHOTOS/'+m.id+'/supplier-'+i+'.'+ext,'image',source);if(d)m.reference_photos.push({path:d.path,url:d.url,source_url:source,rights:'reference_only_permission_required',caption:prod.title+' — external manufacturer product reference.'});}
 }}
 if(m.manufacturer_tds_status!=='downloaded'&&m.brand==='Fiberlogy'){const keys={ 'ABS Easy':['EASYABS'],'ASA Aramid Fiber':['ASAAF','ASA-AF'],'ASA Recycled':['RASA'],'BVOH':['BVOH'],'PA12 Carbon Fiber':['NYLONPA12CF','NYLONPA12CF15'],'PC ABS':['PCABS','PC-ABS'],'PCTG Glass Fiber':['PCTGGF','PCTGGF10'],'PETG Carbon Fiber':['PETGCF'],'PETG ESD':['PETGESD','PETG-ESD'],'PETG Matte':['MATTEPETG','PETGMATTE'],'PETG PTFE':['PETGPTFE'],'PLA Carbon Fiber':['PLACF'],'PP':['PP'],'PP Recycled':['RPP'],'PVB FiberSmooth':['FIBERSMOOTH'],'TPE MattFlex 40D':['MATTFLEX40D']};for(const k of keys[m.material_name]||[]){let u='https://fiberlogy.com/upload/techfiles/FIBERLOGY_'+k+'_TDS.pdf';let d=await get(u,'06_DATASHEETS/fiberlogy-additional/FIBERLOGY_'+k+'_TDS.pdf','pdf',m.source_url);if(d){m.datasheets.push({...d,document_type:'TDS',verification:'Downloaded from manufacturer URL; exact grade label must be checked in the PDF.'});m.manufacturer_tds_status='downloaded';break;}}}
});
// Read numerical processing conditions from each exact manufacturer's TDS without merging grades.
for(const m of records){const tds=m.datasheets.find(x=>x.document_type==='TDS');if(tds){let rel=tds.path.replaceAll('/','__')+'.txt';let text=await fs.readFile(path.join(root,'09_SOURCES/datasheet_text',rel),'utf8').catch(()=>null);if(text?.length>80){let s=text.replace(/\s+/g,' ');const n=s.match(/Nozzle [Tt]emperature\s*(?:\[°C\])?\s*(\d+\s*(?:[–-]|±)\s*\d+\s*(?:\([^)]*\)|°C)?)/)?.[1];const b=s.match(/(?:Build plate temperature|Heatbed Temperature)\s*(?:\[°C\])?\s*(\d+\s*(?:[–-]|±)\s*\d+\s*(?:\([^)]*\)|°C)?)/)?.[1];if(!m.settings.nozzle_temperature&&n)m.settings.nozzle_temperature=n;if(!m.settings.bed_temperature&&b)m.settings.bed_temperature=b;m.settings.exact_tds_url=tds.url;}}
 let spec=m.settings.nozzle_temperature;let bed=m.settings.bed_temperature;function minTemp(s){if(!s)return null;let nums=s.match(/\d+/g)?.map(Number);if(!nums)return null;return s.includes('±')?nums[0]-nums[1]:nums[0];}const n=minTemp(spec),b=minTemp(bed);
 m.printer_compatibility={};for(const [id,max] of [['prusa-xl-5',290],['rat-rig-v-core-4-1-500',350],['modix-big-meter',340]]){let st=m.service_status==='not_verified_for_current_fleet'?'outside_verified_configuration':n!==null&&n>max?'nozzle_requirement_exceeds_published_limit':b!==null&&b>120?'bed_requirement_exceeds_published_limit':n===null?'supplier_conditions_and_process_review_required':m.service_status==='specialist_review_required'?'specialist_process_validation_required':'within_temperature_range_process_validation_required';m.printer_compatibility[id]={status:st,comparison_basis:'Manufacturer published reference limits; installed EVA PRINT configurations require confirmation.',reference_nozzle_limit_c:max,reference_bed_limit_c:120};}
 await fs.writeFile(path.join(root,'02_MATERIALS',m.id,'material.json'),JSON.stringify(m,null,2));let f=path.join(root,'02_MATERIALS',m.id,'description.en.txt');let s=await fs.readFile(f,'utf8');s+='\n\nUpdated exact supplier references\n'+m.datasheets.filter(x=>x.document_type==='TDS').map(x=>x.url+' | '+x.path).join('\n')+'\n'+m.reference_photos.map(x=>x.path+' | '+x.url).join('\n')+'\n';await fs.writeFile(f,s);}
await fs.writeFile(path.join(root,'02_MATERIALS/materials.en.json'),JSON.stringify(records,null,2));await fs.writeFile(path.join(root,'09_SOURCES/download-manifest.json'),JSON.stringify(man,null,2));
const missing=records.filter(m=>m.manufacturer_tds_status!=='downloaded').map(m=>({id:m.id,name:m.name,source:m.source_url,status:'Manufacturer PDF unavailable; local EVA PRINT overview provided.'}));await fs.writeFile(path.join(root,'12_VALIDATION/unavailable-manufacturer-tds.json'),JSON.stringify(missing,null,2));
